import re

UNIT_MAP = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_RE = re.compile(
    r'P(?:(?P<weeks>\d+(?:\.\d+)?)W)?(?:(?P<days>\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(?P<hours>\d+(?:\.\d+)?)H)?(?:(?P<minutes>\d+(?:\.\d+)?)M)?(?:(?P<seconds>\d+(?:\.\d+)?)S)?)?',
    re.IGNORECASE,
)

_CLOCK_RE = re.compile(r'(\d+):(\d+)(?::(\d+(?:\.\d+)?))?')

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("text must not be None")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    # bare non-negative integer, meaning seconds
    if re.fullmatch(r'\d+', s):
        return int(s)

    # ISO 8601 duration
    if s[0].upper() == 'P':
        iso_match = _ISO_RE.fullmatch(s)
        if iso_match:
            gd = iso_match.groupdict()
            if any(v is not None for v in gd.values()):
                total = 0.0
                if gd['weeks'] is not None:
                    total += float(gd['weeks']) * 604800
                if gd['days'] is not None:
                    total += float(gd['days']) * 86400
                if gd['hours'] is not None:
                    total += float(gd['hours']) * 3600
                if gd['minutes'] is not None:
                    total += float(gd['minutes']) * 60
                if gd['seconds'] is not None:
                    total += float(gd['seconds'])
                return round(total)
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")

    # clock notation: hh:mm:ss or mm:ss
    clock_match = _CLOCK_RE.fullmatch(s)
    if clock_match:
        a, b, c = clock_match.groups()
        if c is not None:
            total = int(a) * 3600 + int(b) * 60 + float(c)
        else:
            total = int(a) * 60 + int(b)
        return round(total)

    # number+unit components, possibly separated by spaces
    compact = re.sub(r'\s+', '', s)
    pos = 0
    total = 0.0
    found_any = False
    for m in _COMPONENT_RE.finditer(compact):
        if m.start() != pos:
            raise ValueError(f"invalid duration: {text!r}")
        pos = m.end()
        found_any = True
        num = float(m.group(1))
        unit = m.group(2).lower()
        if unit not in UNIT_MAP:
            if unit.endswith('s') and unit[:-1] in UNIT_MAP:
                unit = unit[:-1]
            else:
                raise ValueError(f"unknown unit: {m.group(2)!r}")
        total += num * UNIT_MAP[unit]

    if not found_any or pos != len(compact):
        raise ValueError(f"invalid duration: {text!r}")

    return round(total)

